use super::*;
fn observe<T>(work:impl FnOnce()->T)->(T,usize,usize){crate::registry::tests::observe_ownership(work)}
#[derive(semio_framework_value::RetireOwned)]
struct AdmissionSources{metadata:SharedOwner<super::super::super::PendingOperatorMetadata>,input:Option<Dictionary>,accepted:Option<OperatorPendingPlan>}
#[test]
fn original_pending_plan_admission_leases_same_metadata_only_after_full_admission(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){for copy in [1,3,64]{
  let(mut sources,born,free)=observe(||AdmissionSources{metadata:SharedOwner::from_cold(super::super::super::PendingOperatorMetadata{extension_id:row["extensionId"].as_str().unwrap().into(),operator_id:row["operatorId"].as_str().unwrap().into()}),input:Some(serde_json::from_value(row["input"].clone()).unwrap()),accepted:None});let original=born-free;let pointer=sources.metadata.as_ptr();let input=sources.input.as_ref().unwrap().entry_at_rank(0).unwrap().1 as *const Value;let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1};
  for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(result,born,free)=observe(||super::super::super::OperatorPlanAdmission::pending(&sources.metadata,sources.input.take().unwrap(),denied));assert_eq!((born,free),(0,0));let(error,original)=result.err().unwrap();assert_eq!(match error{EvalError::Retained(error)=>error.retained_progress(),_=>panic!("original pending plan returned a different refusal family")},Default::default());sources.input=Some(original);assert_eq!(sources.metadata.as_ptr(),pointer);assert_eq!(sources.input.as_ref().unwrap().entry_at_rank(0).unwrap().1 as *const Value,input);}
  let((result,receipt),born,free)=observe(||super::super::super::OperatorPlanAdmission::pending(&sources.metadata,sources.input.take().unwrap(),grant).unwrap());assert!(receipt.fits(grant));assert_eq!(receipt.copied_bytes,0);assert_eq!((born,free),(0,0));let super::super::super::OperatorPlanAdmission::Pending(plan)=result else{panic!("original pending admission lost its typed source")};assert_eq!(plan.metadata.as_ptr(),pointer);assert_eq!(plan.input.entry_at_rank(0).unwrap().1 as *const Value,input);sources.accepted=Some(plan);let(mut owner,born,free)=observe(||ControlledRetirement::new(sources).unwrap_or_else(|_|unreachable!()));assert_eq!((born,free),(0,0));let mut births=0;let mut releases=0;let mut idle=0;for _ in 0..100000{if owner.terminal_is_empty(){break}let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(copy).unwrap(),maximum_release_bytes:owner.next_release_byte_demand().unwrap(),maximum_depth:owner.next_depth_demand().unwrap()};let(step,born,free)=observe(||owner.step(grant).unwrap());let p=step.progress();assert!(p.fits(grant));assert_eq!((born,free),(p.retained_capacity_bytes,p.released_bytes));births+=born;releases+=free;if p==Default::default(){idle+=1}else{idle=0}assert!(idle<64);}assert!(owner.terminal_is_empty());assert_eq!(original+births,releases);assert_eq!(observe(||drop(owner)),((),0,0));eprintln!("[DEBUG] Original pending admission copy={copy} sameMetadata=true sameInput=true deniedBirth=0 terminalDrop=0");
 }}
}
#[test]
fn original_pending_wave_preserves_metadata_input_hash_and_physical_receipts(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){for copy in [1,3,64]{for cancel in [None,Some(0),Some(9),Some(37),Some(101)]{
  let((plan,neuron),born,free)=observe(||(OperatorPendingPlan{metadata:SharedOwner::from_cold(super::super::super::PendingOperatorMetadata{extension_id:row["extensionId"].as_str().unwrap().into(),operator_id:row["operatorId"].as_str().unwrap().into()}),input:serde_json::from_value::<Dictionary>(row["input"].clone()).unwrap()},row["neuronId"].as_str().unwrap().to_string()));let original=born-free;let pointer=plan.metadata.operator_id.as_ptr();let value_pointer=plan.input.entry_at_rank(0).unwrap().1 as *const Value;let expected_hash=super::super::super::node_hash(&plan.metadata.operator_id,&plan.input);
  let(mut cursor,born,free)=observe(||PendingWaveCursor::new(plan));assert_eq!((born,free),(0,0));let mut births=0;let mut releases=0;let mut output=None;let mut blocked=false;let mut idle=0;
  for turn in 0..100000{if cancel==Some(turn){break}let d=cursor.next_demands(&neuron,copy).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let(result,born,free)=observe(||cursor.step(&neuron,RetainedCloneGrant{maximum_items:0,..grant}).unwrap());assert!(result.is_none());assert_eq!(cursor.progress(),Default::default());assert_eq!((born,free),(0,0));let(result,born,free)=observe(||cursor.step(&neuron,grant).unwrap());let receipt=cursor.progress();assert!(receipt.fits(grant));assert_eq!((born,free),(receipt.retained_capacity_bytes,receipt.released_bytes));births+=born;releases+=free;assert_eq!(cursor.sources.as_ref().unwrap().plan.metadata.operator_id.as_ptr(),pointer);assert_eq!(cursor.sources.as_ref().unwrap().plan.input.entry_at_rank(0).unwrap().1 as *const Value,value_pointer);if d.copy_bytes>copy{assert_eq!(receipt,Default::default());assert_eq!((born,free),(0,0));blocked=true;break}if let Some(value)=result{output=Some(value);break}if receipt==Default::default(){idle+=1}else{idle=0}assert!(idle<64,"original wave stalled copy={copy} turn={turn} phase={} demand={d:?}",cursor.phase);}
  if cancel.is_none()&&!blocked{let value=output.as_ref().unwrap();assert_eq!(value.node_hash,expected_hash);assert_eq!(value.neuron_id,neuron);assert_eq!(value.input_json,row["expectedInputJson"].as_str().unwrap());assert_eq!(value.extension_id,row["extensionId"].as_str().unwrap());assert_eq!(value.operator_id,row["operatorId"].as_str().unwrap());}if cancel.is_none()&&copy==1{assert!(blocked);assert!(output.is_none());}
  cursor.begin_close();idle=0;for _ in 0..100000{if cursor.terminal_is_empty(){break}let d=cursor.next_close_demands(copy).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let(step,born,free)=observe(||cursor.close_step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((born,free),(step.progress().retained_capacity_bytes,step.progress().released_bytes));births+=born;releases+=free;if step.progress()==Default::default(){idle+=1}else{idle=0}assert!(idle<64);}assert!(cursor.terminal_is_empty());let(_,born,free)=observe(||drop(cursor));assert_eq!((born,free),(0,0));
  let(mut owner,born,free)=observe(||ControlledRetirement::new((neuron,output)).unwrap_or_else(|_|unreachable!()));assert_eq!((born,free),(0,0));for _ in 0..100000{if owner.terminal_is_empty(){break}let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(copy).unwrap(),maximum_release_bytes:owner.next_release_byte_demand().unwrap(),maximum_depth:owner.next_depth_demand().unwrap()};let(step,born,free)=observe(||owner.step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((born,free),(step.progress().retained_capacity_bytes,step.progress().released_bytes));births+=born;releases+=free;}assert!(owner.terminal_is_empty());assert_eq!(original+births,releases);let(_,born,free)=observe(||drop(owner));assert_eq!((born,free),(0,0));eprintln!("[DEBUG] Original wave id={} copy={copy} cancel={cancel:?} blocked={blocked} births={births} releases={releases} terminalDrop=0",row["id"]);
 }}}
}
